package com.ruoyi.framework.audit;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.dao.DataAccessResourceFailureException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class AuditCaptureFallbackTest {
 @Test void coreEventConstructionNeedsNoDatabase(){var j=mock(JdbcTemplate.class);var c=new AuditContext();c.path="/metal/work-order";c.verb="POST";c.actorId=2L;c.actorFactory=7L;var result=new AuditRecorder(j,mock(PlatformTransactionManager.class)).event(c,"SYSTEM_ERROR","outage",null);assertEquals(7L,result.get("factory"));verifyNoInteractions(j);}
 @Test void metadataFailureAloneDoesNotRequireFileFallback(){var j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenThrow(new DataAccessResourceFailureException("name unavailable"));var m=mock(PlatformTransactionManager.class);when(m.getTransaction(any())).thenReturn(new SimpleTransactionStatus());var c=new AuditContext();c.path="/metal/work-order";c.verb="POST";c.actorId=2L;c.actorFactory=7L;try(var files=mockStatic(AuditRecorder.class,CALLS_REAL_METHODS)){new AuditRecorder(j,m).failure(c,"BUSINESS_REJECTED","reason");assertTrue(c.logged);files.verifyNoInteractions();verify(j).update(contains("audit_outbox"),eq(c.event),contains("factoryNameUnavailable"));}}
 @Test void nameUnavailableMarkerPreventsReplayFromGuessingCurrentName()throws Exception{var j=mock(JdbcTemplate.class);var d=new AuditDelivery(j,mock(PlatformTransactionManager.class));var store=AuditDelivery.class.getDeclaredMethod("store",com.alibaba.fastjson2.JSONObject.class);store.setAccessible(true);var e=com.alibaba.fastjson2.JSON.parseObject("{\"kind\":\"operation\",\"event\":\"fixture\",\"factory\":7,\"factoryNameUnavailable\":true,\"time\":\"2026-10-23T10:00:00\",\"code\":\"BUSINESS_REJECTED\"}");store.invoke(d,e);verify(j,never()).queryForList(contains("SELECT factory_name"),any(Object[].class));}
 @Test void fallbackWritesSameEventAndReportsDiskFailure(@org.junit.jupiter.api.io.TempDir java.nio.file.Path dir)throws Exception{
  var event=new LinkedHashMap<String,Object>();event.put("event","stable-event");event.put("trace","trace");event.put("request","redacted");
  var target=dir.resolve("fallback.jsonl");AuditRecorder.fallback(event,target);var saved=com.alibaba.fastjson2.JSON.parseObject(java.nio.file.Files.readString(target));assertEquals("stable-event",saved.getString("event"));
  var logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(AuditRecorder.class);var appender=new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();appender.start();logger.addAppender(appender);
  try{AuditRecorder.fallback(event,dir);assertEquals(1,appender.list.size());var message=appender.list.get(0).getFormattedMessage();assertTrue(message.contains("AUDIT_FALLBACK_WRITE_FAILED"));assertTrue(message.contains("stable-event"));assertFalse(message.contains("redacted"));}finally{logger.detachAppender(appender);appender.stop();}
 }
}
